/** Record the medicines a patient brought in — POST /api/v1/admissions/{admission_id}/own-medicines (who may call: holders of patient.own_medicine.record). */
export function recordOwn(admission_id: number, body: OwnMedicinesIn): Promise<OwnMedicineOut[]> {
  return api<OwnMedicineOut[]>("POST", `/admissions/${admission_id}/own-medicines`, body, { idempotent: true });
}

/** The patient's own medicines — GET /api/v1/admissions/{admission_id}/own-medicines (who may call: holders of patient.own_medicine.record or patient.own_medicine.identify or prescription.view). */
export function listOwn(admission_id: number): Promise<OwnMedicineOut[]> {
  return api<OwnMedicineOut[]>("GET", `/admissions/${admission_id}/own-medicines`, undefined);
}

/** Hand the patient's own medicines back — POST /api/v1/admissions/{admission_id}/own-medicines/hand-back (who may call: holders of patient.own_medicine.record). */
export function handBackOwn(admission_id: number, body: OwnMedicineHandBackIn): Promise<OwnMedicineOut[]> {
  return api<OwnMedicineOut[]>("POST", `/admissions/${admission_id}/own-medicines/hand-back`, body, { idempotent: true });
}

/** Destroy a patient's own medicine — POST /api/v1/own-medicines/{own_medicine_id}/destroy (who may call: holders of patient.own_medicine.record). */
export function destroyOwn(own_medicine_id: number, body: OwnMedicineDestroyIn): Promise<OwnMedicineOut> {
  return api<OwnMedicineOut>("POST", `/own-medicines/${own_medicine_id}/destroy`, body);
}

/** Medication safety work waiting — GET /api/v1/medication-safety/worklist (who may call: holders of medication.safety.view or patient.wristband.print). */
export function safetyWorklist(query?: { ward_id?: number | null; mine?: boolean }): Promise<MedicationWorklistItemOut[]> {
  return api<MedicationWorklistItemOut[]>("GET", withQuery(`/medication-safety/worklist`, query), undefined);
}
